verus! {
    use vstd::prelude::*;

    /// Given a finite Vec of Vec<char>, returns
    ///   - None if the input is empty,
    ///   - Otherwise Some(seq) where seq is exactly one of the input vectors,
    ///     of maximum length, and among those with maximum length is the earliest one.
    fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>>
        // If we return None exactly when the input is empty
        ensures match result {
            None => strings.len() == 0,
            Some(_) => strings.len() > 0
        }
        // In the non‐empty case, the returned vector `seq` has the required properties:
        // 1) It is equal to strings[i] for some i.
        // 2) Every input vector has length ≤ seq.len().
        // 3) For every j < i, strings[j].len() < seq.len() (i.e., earliest max‐length).
        ensures match result {
            None => true,
            Some(ref seq) => {
                // exists an index i
                exists |i: usize| i < strings.len() &&
                    // equality to one of the inputs
                    strings[i] == *seq &&
                    // maximality
                    (forall |j: usize| j < strings.len() ==> strings[j].len() <= seq.len()) &&
                    // earliest among maxima
                    (forall |j: usize| j < i ==> strings[j].len() < seq.len())
            }
        }
    {
        if strings.len() == 0 {
            return None;
        }

        // We know strings.len() ≥ 1 here
        let mut best_index: usize = 0;
        let mut i: usize = 1;

        // Scan the rest, maintaining that among [0..i) the best index
        // points to a longest‐so‐far vector, and best_index < i.
        while i < strings.len()
            invariant i <= strings.len()
            invariant best_index < i
            // forall k < i, strings[best_index].len() ≥ strings[k].len()
            invariant forall |k: usize| k < i ==> strings[best_index].len() >= strings[k].len()
            decreases strings.len() - i
        {
            if strings[i].len() > strings[best_index].len() {
                best_index = i;
            }
            i += 1;
        }

        // At the end, best_index ∈ [0..strings.len()) is the earliest longest.
        Some(strings[best_index].clone())
    }
}